def icon(kind='arrow'):
 p={'arrow':'<path d="M4 12h15M13 5l7 7-7 7"/>','external':'<path d="M5 19 19 5M5 5h14v14"/>','left':'<path d="m14 5-7 7 7 7"/>','right':'<path d="m9 5 7 7-7 7"/>','close':'<path d="m6 6 12 12M6 18 18 6"/>','plus':'<path d="M12 4v16M4 12h16"/>','expand':'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5"/>'}[kind]
