 nxt=data[(i+1)%len(data)]
 body=f'''{bread(c['name'],True)}<section class="category-intro shell"><div><span class="eyebrow">Portafolio / 0{i+1}</span><h1>{c['name']}<span class="title-count">{len(c['projects']):02d}</span></h1><h2>{c['title']}</h2><p>{c['description']}</p></div><div class="category-graphic" aria-hidden="true"><div class="category-symbol symbol-{c['id']}"><i></i><i></i><i></i><i></i></div><span>A1 / {c['name'].upper()}</span></div></section><section class="shell category-selection"><div class="catalog-meta"><span>Selección de proyectos</span><span>{len(c['projects']):02d} trabajos</span></div>{names}<p class="collection-note">Seguimos incorporando fotografías de los proyectos a esta selección. Mientras tanto, podés conocer más del taller en <a href="{IG}" target="_blank" rel="noopener noreferrer">Instagram</a>.</p></section><section class="next-category shell"><span class="eyebrow">Seguí explorando</span><a href="{nxt['id']}.html"><span>{nxt['name']}</span>{icon('arrow')}</a></section>{cta()}'''
