about=f'''{bread('Nosotros')}<section class="page-intro shell"><span class="eyebrow">Nosotros / A1 Maquetas</span><h1>Un oficio.<br><em>Muchas perspectivas.</em></h1><div class="page-lead"><p>Somos de Asunción y hemos realizado trabajos internacionales. Hace más de 20 años hacemos maquetas: ideas que se convierten en piezas para mirar de cerca.</p></div></section><section class="about-story shell"><div class="about-story-photo"><img src="assets/photos/a1-residencial.jpg" width="1920" height="1503" alt="Fachada y detalles de una maqueta residencial A1, archivo de 2015."><a class="photo-credit" href="{ABC}" target="_blank" rel="noopener noreferrer">Archivo A1 / ABC Color, 2015 {icon('external')}</a></div><div class="about-story-copy"><span class="eyebrow">Nuestra forma de mirar</span><h2>La arquitectura<br>se entiende mejor<br>cuando toma forma.</h2><p>Un plano propone. Una maqueta acerca. Permite observar un proyecto desde otra perspectiva y reconocer la relación entre el conjunto y sus detalles.</p><p>En A1, el trabajo de Hernán Kiss y el taller se expresa en edificios, loteamientos, viviendas, piezas especiales y maquetas hápticas.</p><div class="signature">Hernán Kiss<span>A1 Maquetas / Asunción, Paraguay</span></div></div></section><section class="about-band"><div class="shell about-grid"><div class="experience-number"><span>+20</span><p>Años de experiencia<br>haciendo maquetas.</p></div><div><span class="eyebrow">Origen y trayectoria</span><h2>Desde Paraguay.<br>Para proyectos<br><em>sin fronteras.</em></h2><p>Nuestro punto de partida es Asunción. Nuestra experiencia incluye trabajos nacionales e internacionales, con una misma atención puesta en cada maqueta.</p></div></div></section><section class="shell principles"><span class="eyebrow">Tres formas de acercarnos a una idea</span><div class="principle-grid"><article><span>01</span><h2>Escala.</h2><p>Encontrar la relación que permite comprender el proyecto.</p></article><article><span>02</span><h2>Materia.</h2><p>Dar una presencia tangible a la propuesta arquitectónica.</p></article><article><span>03</span><h2>Detalle.</h2><p>Hacer que cada parte dialogue con el conjunto.</p></article></div></section>{cta()}'''
page('nosotros.html','Nosotros','A1 Maquetas, Asunción. Más de 20 años de experiencia haciendo maquetas y trabajos nacionales e internacionales.',about,'Nosotros')
quote_body=f'''{bread('Cotización')}<section class="page-intro shell"><span class="eyebrow">Contacto / Contanos tu proyecto</span><h1>El primer paso<br>es <em>conocer tu proyecto.</em></h1><div class="page-lead"><p>Para cotizar una maqueta podés compartirnos información sobre tu proyecto, planos, perspectivas y modelo 3D.</p></div></section><section class="shell quote-requirements" aria-label="Información útil para cotizar">{requirements()}</section><section class="brief-section shell"><div class="brief-intro"><span class="eyebrow">Escribinos</span><h2>De la idea<br>a la conversación.</h2><p>Contanos qué necesitás y reuní los archivos que nos ayuden a entender tu proyecto.</p><div class="contact-emails"><p><strong>Presupuestos y proyectos</strong><br><a href="mailto:presupuestos@a1maquetas.com.py">presupuestos@a1maquetas.com.py</a></p><p><strong>Contacto con Hernán Kiss</strong><br><a href="mailto:hernankiss@a1maquetas.com.py">hernankiss@a1maquetas.com.py</a></p></div></div><form id="briefForm" class="brief-form" method="post" enctype="multipart/form-data"><div class="field-grid"><label>Tu nombre<input name="nombre" required maxlength="100" autocomplete="name" placeholder="¿Cómo te llamás?"></label><label>Tu correo electrónico<input type="email" name="email" required maxlength="254" autocomplete="email" placeholder="nombre@correo.com"></label></div><div class="field-grid"><label>Tipo de proyecto<select name="categoria" required><option value="">Elegí una categoría</option>{''.join(f'<option>{c["name"]}</option>' for c in data)}</select></label><label>Teléfono <span class="optional">(opcional)</span><input type="tel" name="telefono" autocomplete="tel" placeholder="Tu número de contacto"></label></div><label>Nombre o referencia del proyecto<input name="referencia" id="briefReference" maxlength="120" placeholder="Nombre del proyecto (opcional)"></label><label>Contanos sobre tu idea<textarea name="detalles" rows="5" maxlength="3000" required placeholder="Qué querés representar y cómo te podemos ayudar"></textarea></label><p class="brief-help">Al preparar la consulta se abrirá tu aplicación de correo. Allí podrás adjuntar planos, imágenes o archivos antes de enviarla.</p><button class="button" type="submit" aria-describedby="sendStatus">Preparar correo {icon('arrow')}</button><p class="form-note" id="sendStatus">Revisá el correo y adjuntá tus archivos antes de enviarlo.</p></form></section>{cta()}'''
page('cotizacion.html','Cotizá tu maqueta','Qué necesitamos para cotizar: legajo de obra, perspectivas y modelo 3D. Prepará tu consulta para A1 Maquetas.',quote_body,'Cotización')
